type Select struct { current int; items []*Option }   // one owner
type Option struct { parent *Select; Value int }

func (s *Select) NewOption(v int) *Option {        // child attaches itself
    o := &Option{parent: s, Value: v}
    s.items = append(s.items, o)
    return o
}
func (s *Select) Activate(v int) { s.current = v }  // parent enforces one-of-N
